// updateOps queues Update's writes onto ops, for a Batch: the value-object
// rows that replace the masked ones, the row update, then the removal of what
// they replaced. With in.Etag set the update is guarded inside the batch: a
// self-update of the key whose post-check asserts the etag fails the request
// when the record moved on, and the guarded update after it writes the row.
//
// outputPaths names the server-owned fields written alongside
// (Update<Model>WithOutputOnly); nil for Update.
func (r *GraphQLUserRepository) updateOps(ctx context.Context, ops *repox.Ops, id string, in *userv1.User, paths, outputPaths []string) (repox.Check, error) {
	row, err := r.Svc.Query.User.Resource.Get(ctx, id)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if row == nil {
		return nil, repox.ErrNotFound
	}
	existingPB := userFromRow(row)
	if in.GetEtag() != "" && existingPB.GetEtag() != in.GetEtag() {
		return nil, repox.ErrConflict
	}
	var staleNameComponents string
	staleEnterprise := repox.Deref(row.EnterpriseId)
	var old27 []string
	{
		rows28, err := r.Svc.Query.User.Address.List(ctx, addressql.List().Where(addressql.UserId.Eq(id)))
		if err != nil {
			return nil, mapGraphQLErr(err)
		}
		for i := range rows28 {
			old27 = append(old27, rows28[i].Id)
		}
	}
	staleAddresses := old27
	merged := proto.Clone(existingPB).(*userv1.User)
	applyUserMask(merged, in, paths)
	repox.CopyFields(merged, in, outputPaths)
	patch := userToUpdatePatch(merged)
	if len(outputPaths) > 0 {
		userAddOutputPatch(&patch, merged, outputPaths)
	}
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	var utx, atx repox.Ops
	if repox.GroupTouched(paths, "name_components") {
		staleNameComponents = repox.Deref(row.NameComponentsId)
		patch.NameComponentsId = graphql.Null[string]()
		if v := merged.GetNameComponents(); v != nil {
			vi := userNameToCreateInput(v)
			vi.Id = repox.NewULID()
			utx.Add(r.Svc.Mutation.User.Names.CreateOp(vi, new(namesql.InsertUserNamesResponse)))
			patch.NameComponentsId = graphql.Value(vi.Id)
		}
	}
	if repox.GroupTouched(paths, "enterprise") {
		if id := staleEnterprise; id != "" {
			got21, err := r.Svc.Query.User.EnterpriseUsers.Get(ctx, id)
			if err != nil {
				return nil, mapGraphQLErr(err)
			}
			if got21 != nil {
				atx.Add(r.Svc.Mutation.User.EnterpriseUsers.DeleteOp(got21.Id, new(enterpriseusersql.DeleteUserEnterpriseUsersByIdResponse)))
				if id := repox.Deref(got21.ManagerId); id != "" {
					got22, err := r.Svc.Query.User.Managers.Get(ctx, id)
					if err != nil {
						return nil, mapGraphQLErr(err)
					}
					if got22 != nil {
						atx.Add(r.Svc.Mutation.User.Managers.DeleteOp(got22.Id, new(managersql.DeleteUserManagersByIdResponse)))
					}
				}
			}
		}
		patch.EnterpriseId = graphql.Null[string]()
		if v23 := merged.GetEnterprise(); v23 != nil {
			n24 := userEnterpriseUserToCreateInput(v23)
			n24.Id = repox.NewULID()
			if v25 := v23.GetManager(); v25 != nil {
				n26 := userManagerToCreateInput(v25)
				n26.Id = repox.NewULID()
				utx.Add(r.Svc.Mutation.User.Managers.CreateOp(n26, new(managersql.InsertUserManagersResponse)))
				n24.ManagerId = n26.Id
			}
			utx.Add(r.Svc.Mutation.User.EnterpriseUsers.CreateOp(n24, new(enterpriseusersql.InsertUserEnterpriseUsersResponse)))
			patch.EnterpriseId = graphql.Value(n24.Id)
		}
	}
	if repox.GroupTouched(paths, "addresses") {
		for _, oid := range staleAddresses {
			if id := oid; id != "" {
				got29, err := r.Svc.Query.User.Address.Get(ctx, id)
				if err != nil {
					return nil, mapGraphQLErr(err)
				}
				if got29 != nil {
					atx.Add(r.Svc.Mutation.User.Address.DeleteOp(got29.Id, new(addressql.DeleteUserAddressByIdResponse)))
				}
			}
		}
		for _, v30 := range merged.GetAddresses() {
			n31 := userAddressToCreateInput(v30)
			n31.Id = repox.NewULID()
			n31.UserId = id
			atx.Add(r.Svc.Mutation.User.Address.CreateOp(n31, new(addressql.InsertUserAddressResponse)))
		}
	}
	*ops = append(*ops, utx...)
	resp := new(resourceql.UpdateUserResourceByIdResponse)
	etag := in.GetEtag()
	if etag != "" {
		ops.Add(r.Svc.Mutation.User.Resource.UpdateOp(id, resourceql.UpdateInput{Id: graphql.Value(id)}, new(resourceql.UpdateUserResourceByIdResponse), resourceql.Update().PostCheck(resourceql.Etag.Eq(etag))))
		ops.Add(r.Svc.Mutation.User.Resource.UpdateOp(id, patch, resp, resourceql.Update().PreCheck(resourceql.Etag.Eq(etag))))
	} else {
		ops.Add(r.Svc.Mutation.User.Resource.UpdateOp(id, patch, resp))
	}
	if staleNameComponents != "" {
		atx.Add(r.Svc.Mutation.User.Names.DeleteOp(staleNameComponents, new(namesql.DeleteUserNamesByIdResponse)))
	}
	*ops = append(*ops, atx...)
	return func(ctx context.Context, failed error) error {
		if failed == nil {
			if resp.AffectedRows == 0 {
				if etag != "" {
					return repox.ErrConflict
				}
				return repox.ErrNotFound
			}
			return nil
		}
		// The request failed; if this guard is why, say so.
		if etag != "" {
			if now, err := r.Svc.Query.User.Resource.Get(ctx, id); err == nil && (now == nil || userFromRow(now).GetEtag() != etag) {
				return repox.ErrConflict
			}
		}
		return nil
	}, nil
}

