// Compile-time proof the adapter satisfies the interface.
var _ UserRepository = (*GraphQLUserRepository)(nil)

// graphQLBatch is Batch on GraphQL: queued writes go into the Unit's mutation
// request on Commit (see repox.Unit.Commit). A guarded UpdateOutputOnly runs
// ahead of it, one by one: the engine reports its failed guard by touching no
// row, which cannot abort a request.
type graphQLBatch struct {
	u         *repox.Unit
	svc       *freebusyql.Service
	retention time.Duration
	// keys holds the row key of every record this batch creates, by name: a
	// later write in the batch finds its row here, since it is not stored
	// until the batch's request runs.
	keys map[string]string
}

// Commit applies the Unit's writes; see repox.Unit.Commit.
func (b *graphQLBatch) Commit(ctx context.Context) error { return b.u.Commit(ctx) }

// rowID returns the row key of the record named name: one this batch creates,
// else what resolve (a repository's rowID) finds.
func (b *graphQLBatch) rowID(ctx context.Context, name string, resolve func(context.Context, string) (string, error)) (string, error) {
	if id, ok := b.keys[name]; ok {
		return id, nil
	}
	return resolve(ctx, name)
}

// CreateUser queues a create and returns the name the record will have.
func (b *graphQLBatch) CreateUser(in *userv1.User) (string, error) {
	r := &GraphQLUserRepository{Svc: b.svc}
	ci, named, err := r.newInput(in)
	if err != nil {
		return "", err
	}
	if b.keys == nil {
		b.keys = map[string]string{}
	}
	b.keys[named.GetName()] = ci.Id
	queueUserReferences(b.u, named, nil)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		return r.insertOps(ctx, ops, named, ci)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/User", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

// UpdateUser queues Update; in.Etag, when set, guards it inside the
// batch's request (see updateOps).
func (b *graphQLBatch) UpdateUser(in *userv1.User, paths []string) {
	if _, err := repox.SplitName(in.GetName(), "users"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLUserRepository{Svc: b.svc}
	queueUserReferences(b.u, in, paths)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		return r.updateOps(ctx, ops, id, in, paths, nil)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/User", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getUser)})
}

// UpdateUserWithOutputOnly queues UpdateWithOutputOnly; in.Etag, when
// set, guards it inside the batch's request, as UpdateUser's does.
func (b *graphQLBatch) UpdateUserWithOutputOnly(in *userv1.User, paths, outputPaths []string) {
	if _, err := repox.SplitName(in.GetName(), "users"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLUserRepository{Svc: b.svc}
	queueUserReferences(b.u, in, paths)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		return r.updateOps(ctx, ops, id, in, paths, outputPaths)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/User", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getUser)})
}

// UpdateUserOutputOnly queues UpdateOutputOnly; in.Etag, when set, guards
// it, and a guarded update runs ahead of the batch (see graphQLBatch).
func (b *graphQLBatch) UpdateUserOutputOnly(in *userv1.User, paths []string) {
	if len(paths) == 0 {
		b.u.Fail(fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument))
		return
	}
	if _, err := repox.SplitName(in.GetName(), "users"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLUserRepository{Svc: b.svc}
	patch := userToOutputPatch(in, paths)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/User", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getUser)})
	if etag := in.GetEtag(); etag != "" {
		b.u.QueueGraphQLAhead(func(ctx context.Context) error {
			id, err := b.rowID(ctx, in.GetName(), r.rowID)
			if err != nil {
				return err
			}
			_, err = b.svc.Mutation.User.Resource.UpdateIfMatch(ctx, id, patch, resourceql.Etag.Eq(etag))
			return mapGraphQLErr(err)
		})
		return
	}
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.User.Resource.UpdateOp(id, patch, new(resourceql.UpdateUserResourceByIdResponse)))
		return nil, nil
	})
}

// DeleteUser queues a soft delete. A record already deleted or gone is
// not an error.
func (b *graphQLBatch) DeleteUser(name string) {
	if _, err := repox.SplitName(name, "users"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLUserRepository{Svc: b.svc, Retention: b.retention}
	queueUserDelete(b.u, name, false)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.User.Resource.UpdateOp(id, r.deletePatch(), new(resourceql.UpdateUserResourceByIdResponse), resourceql.Update().PreCheck(resourceql.DeleteTime.IsNull(true))))
		return nil, nil
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/User", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getUser)})
}

// PurgeUser queues the record's removal for good. A record already
// gone is not an error.
func (b *graphQLBatch) PurgeUser(name string) {
	if _, err := repox.SplitName(name, "users"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLUserRepository{Svc: b.svc, Refs: b.u.Conn().References}
	// A record a referrer in another database or service names is kept, as
	// Purge keeps it. One a foreign key of
	// this database still names fails the commit with
	// repox.ErrForeignKey: the request is one transaction, and the engine
	// cannot skip one of its mutations.
	keep := queueUserPurge(b.u, name)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		if *keep {
			return nil, nil
		}
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		return r.purgeOps(ctx, ops, id)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/User", Name: name, Op: repox.ChangePurge, LoadPrior: repox.PriorOf(name, getUser)})
}
